<script setup>
import DramaImageEditor from './DramaImageEditor.vue';
import {dramaImages,validateDramaImages} from './images.js';
import {productionCompanyOptions} from './companies.js';
const props=defineProps({scheduleArtists:{type:Array,default:()=>[]}});

import {ref,computed} from 'vue';
import {initialData} from './seed.js';
import {dramaTypes,validateDrama,generateSchedule} from './schedule.js';
const emit=defineEmits(['close']);
const db=ref(structuredClone(initialData)),error=ref('');
let draft;try{draft=JSON.parse(localStorage.getItem('chob-public-drama-draft'));if(!draft||!Array.isArray(draft.rules)||!Array.isArray(draft.cast))draft=null;}catch{}
const editing=ref(draft||{id:crypto.randomUUID(),titleZh:'',titleEn:'',titleTh:'',types:[],production:'未开机',poster:'',source:'',synopsis:'',cast:[],rules:[]});
function addRule(){editing.value.rules.push({id:crypto.randomUUID(),platformId:'youtube',premiere:'',totalEpisodes:12,intervalDays:7,episodesPerRelease:1,time:'21:30',timezone:'Asia/Bangkok'});}
function addCast(){editing.value.cast.push({artistId:'artist-a',name:'Artist A',role:'',lead:false});}
function saveDraft(){try{localStorage.setItem('chob-public-drama-draft',JSON.stringify(editing.value));error.value='草稿已保存，下次新增时继续填写；未生成排期。';}catch{error.value='草稿保存失败，请勿关闭窗口。';}}
function save(){try{validateDrama(editing.value);validateDramaImages(editing.value);for(const rule of editing.value.rules)generateSchedule(editing.value,rule);const rows=JSON.parse(localStorage.getItem('chob-public-drama-pending')||'[]');const i=rows.findIndex(d=>d.id===editing.value.id);const entry={...editing.value,status:'local_pending'};if(i<0)rows.push(entry);else rows[i]=entry;localStorage.setItem('chob-public-drama-pending',JSON.stringify(rows));localStorage.removeItem('chob-public-drama-draft');error.value='已保存到本机待提交列表，未公开。正式审核提交尚未接通。';}catch(e){error.value=e.message;}}
const companyChoices=computed(()=>productionCompanyOptions(props.scheduleArtists.length?props.scheduleArtists:db.value.artists,editing.value?.productionCompany||''));
function setImages(images){editing.value.images=images;editing.value.poster=images.find(url=>url.trim())||'';}
</script>
<template><Teleport to="body"><div v-if="editing" class="overlay" @click.self="$emit('close')"><form class="dialog editor" @submit.prevent="save"><button type="button" class="close" @click="$emit('close')">取消 ×</button><h2>新增剧集</h2><p class="muted">测试录入：保存与草稿仅保存在本机，不会公开发布。</p><p class="muted">三种剧名至少填写一项；没有明确首播日期时只进入剧集库。</p><label v-for="(label,k) in {titleZh:'中文名',titleEn:'英文名',titleTh:'泰语名',source:'官方来源链接'}">{{label}}<input v-model="editing[k]"></label><DramaImageEditor :model-value="editing.images||(dramaImages(editing).length?dramaImages(editing):[''])" @update:model-value="setImages" /><label>出品公司<select v-model="editing.productionCompany"><option :value="undefined">请选择出品公司</option><option value="">待公布</option><option v-for="company in companyChoices" :key="company" :value="company">{{company}}</option></select><small v-if="!companyChoices.length">暂无公司资料，载入 Schedule 艺人资料库后可选择。</small></label><label>简介<textarea v-model="editing.synopsis"></textarea></label><fieldset><legend>类型</legend><div class="type-grid"><label v-for="t in dramaTypes" class="inline"><input type="checkbox" v-model="editing.types" :value="t">{{t}}</label></div></fieldset><label>制作进度<select v-model="editing.production"><option>未开机</option><option>已开机</option><option>已杀青</option></select></label><h3>卡司</h3><div class="panel" v-for="(c,i) in editing.cast"><select v-model="c.artistId" @change="c.name=db.artists.find(a=>a.id===c.artistId)?.name"><option v-for="a in db.artists" :value="a.id">{{a.name}}</option></select><input v-model="c.role" placeholder="角色名称"><label class="inline"><input type="checkbox" v-model="c.lead">主演</label><button type="button" @click="editing.cast.splice(i,1)">移除</button></div><button type="button" @click="addCast">＋ 卡司</button><h3>播出安排</h3><div class="panel" v-for="(r,i) in editing.rules"><label>平台<select v-model="r.platformId"><option v-for="p in db.platforms" :value="p.id">{{p.name}}</option></select></label><label>首播日期<input type="date" v-model="r.premiere"></label><label>总集数<input type="number" min="1" max="1000" v-model.number="r.totalEpisodes"></label><label>每隔几天更新<input type="number" min="1" max="1000" v-model.number="r.intervalDays"></label><label>每次更新集数<input type="number" min="1" max="1000" v-model.number="r.episodesPerRelease"></label><label>播出时间<input type="time" v-model="r.time"></label><label>时区<select v-model="r.timezone"><option>Asia/Bangkok</option><option>Asia/Shanghai</option><option>UTC</option></select></label><button type="button" @click="editing.rules.splice(i,1)">移除此平台排期</button></div><div class="rule-add-row"><button type="button" @click="addRule">＋ 平台排期</button></div><p v-if="error" role="alert" class="error">{{error}}</p><div class="form-actions"><button type="button" @click="saveDraft">存草稿</button><button class="primary">保存</button></div></form></div>
</Teleport></template><style scoped>
