rder:0;border-left:3px solid #8ca37b;border-radius:4px}.chip small{display:block;font-size:10px}.changed{background:#f7e9e2;border-color:#c69077}.strike{text-decoration:line-through}.event{background:#f1ecf7;border-color:#a48cbf}.cards{display:grid;grid-template-columns:repeat(2,1fr);gap:22px}.card{background:white;padding:18px;border:1px solid #e1e5dc;border-radius:12px}.card-main{display:flex;gap:22px;text-align:left;width:100%;border:0;padding:0;background:none}.card-main img,.poster{width:115px;height:160px;object-fit:cover;border-radius:6px;flex-shrink:0}.poster{background:linear-gradient(145deg,#bdcbb4,#758d75);color:white;display:grid;place-content:center;text-align:center;font:20px Georgia;letter-spacing:3px}.badge{font-size:11px;background:#edf1e6;padding:4px 9px;border-radius:20px}.card h2{font-size:20px;margin:10px 0}.card p{font-size:12px;margin:5px 0}.card>button:last-child{margin-top:12px;font-size:12px}.overlay{position:fixed;inset:0;background:#16261f66;display:flex;align-items:center;justify-content:center;z-index:10;padding:24px}.dialog{position:relative;background:#faf9f6;border-radius:14px;padding:32px;width:650px;max-height:90vh;overflow:auto;box-shadow:0 20px 80px #14271d44}.close{float:right}.hero{position:relative;clear:both}.hero img{width:100%;max-height:280px;object-fit:contain}.banner{background:#f0d9c9;padding:16px;margin:18px 0}.banner strong{display:block;font-size:18px}.banner span{font-size:15px}.announcement{background:#f3e8db;border-radius:8px;padding:15px;margin:15px 0}.announcement p{margin:7px 0}.platform{display:inline-flex;align-items:center;gap:4px;flex-wrap:wrap}.platform img{height:16px;width:auto;max-width:70px;object-fit:contain}.editor label{display:flex;flex-direction:column;gap:5px;margin:12px 0}.editor .inline{display:inline-flex;flex-direction:row;margin-right:14px;align-items:center}.editor input[type=checkbox]{width:auto}.panel{border:1px solid #dce2d7;padding:15px;border-radius:8px;margin:15px 0}.panel input,.panel select{margin:5px}.event-row{display:flex;align-items:center;gap:14px;flex-wrap:wrap;width:100%;padding:18px;border-bottom:1px solid #dce2d7}.event-row label{display:flex;flex-direction:column}.error{color:#a33e29}footer{padding:25px 5%;border-top:1px solid #e1e5dc;font-size:11px;letter-spacing:2px;color:#8b9288}footer span{float:right}@media(max-width:700px){main{padding:20px 12px}.private{font-size:10px}header{gap:8px;padding:15px}.heading{align-items:start}h1{font-size:30px}h1 em{display:block;margin:0;font-size:17px}.cards{grid-template-columns:1fr}.calendar{min-width:700px}section:has(>.calendar){overflow:auto}.day{min-height:120px}nav{gap:10px}nav button{font-size:13px}.dialog{padding:22px}.toolbar{font-size:11px}.overlay{padding:10px}}
.editor fieldset{border:0;padding:0;margin:24px 0;min-width:0}.editor fieldset legend{padding:0;margin-bottom:14px}.editor fieldset .inline{margin:0;display:flex;gap:9px;align-items:center}.type-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px 24px}.editor .form-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:26px;padding-top:20px;border-top:1px solid #e1e5dc}.rule-add-row{display:block;margin:18px 0}@media(max-width:500px){.type-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}}
.overlay{z-index:1000;padding:16px;overflow-y:auto;overscroll-behavior:contain;font:15px/1.6 system-ui,-apple-system,'Microsoft YaHei',sans-serif;color:#303b35}.overlay,.overlay *{box-sizing:border-box}.dialog{width:min(720px,100%);min-width:0;max-width:100%;max-height:calc(100dvh - 32px);margin:auto;padding:clamp(18px,3vw,32px);overflow-x:hidden;overflow-y:auto;overscroll-behavior:contain;scrollbar-gutter:stable}.editor input:not([type=checkbox]),.editor select,.editor textarea{display:block;width:100%;min-width:0;max-width:100%}.editor .panel input,.editor .panel select{margin:5px 0}.editor .close{position:sticky;top:0;z-index:1;background:#faf9f6}.editor .form-actions{position:sticky;bottom:-1px;background:#faf9f6;padding-bottom:12px}.heading{gap:16px;flex-wrap:wrap}.cards{grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr))}.card-main>div:last-child{min-width:0;overflow-wrap:anywhere}.shell{min-width:0}main{width:100%;min-width:0}.event-row>*{min-width:0;max-width:100%}@media(max-width:520px){.overlay{padding:8px}.dialog{max-height:calc(100dvh - 16px);padding:18px;border-radius:12px}.editor .form-actions{gap:8px}.editor .form-actions button{flex:1}.card-main{gap:12px}.card-main img,.poster{width:86px;height:128px}.event-row{padding:12px 0}.heading h1{font-size:28px}nav{gap:8px;flex-wrap:wrap}}
